<dialog data-file-preview-dialog class="m-auto max-h-[90vh] overflow-hidden rounded-2xl border-0 bg-white p-0 text-slate-900 shadow-2xl backdrop:bg-slate-950/80" style="width: min(94vw, 64rem); max-width: 64rem">
    <div class="flex items-center justify-between gap-4 border-b border-slate-200 px-4 py-3">
        <p data-file-preview-title class="truncate text-sm font-semibold">Pratinjau dokumen</p>
        <button type="button" data-file-preview-close aria-label="Tutup pratinjau dokumen" class="grid size-9 shrink-0 place-items-center rounded-lg text-xl text-slate-600 transition hover:bg-slate-100 hover:text-slate-950 focus-visible:outline focus-visible:outline-2 focus-visible:outline-blue-600">&times;</button>
    </div>
    <iframe data-file-preview-frame title="Pratinjau dokumen" src="about:blank" class="block w-full border-0 bg-slate-100" style="height: min(78vh, 54rem)"></iframe>
</dialog>
